from anton.application.llm_schemas.character_edit import EditedCharacter
from anton.domain.models import Character


# Relationships hold ids of other characters, which the model could break; the history is not part of the profile.
NOT_EDITED_FIELDS = {"id", "relationships", "history"}


class CharacterTarget:
    """Let an editing agent revise one character profile; characters are generated by the character service."""

    name = "character"
    chat_prompt = "character_edit_chat.md"
    edit_prompt = "character_edit.md"
    edit_schema = EditedCharacter

    def view(self, data: Character) -> dict:
        """Show the model the profile without the id, the relationships and the history."""
        return data.model_dump(exclude=NOT_EDITED_FIELDS)

    def apply(self, data: Character, edited: EditedCharacter) -> Character:
        """Take the profile from the model and keep the id, the relationships and the history."""
        return Character(id=data.id, relationships=data.relationships, history=data.history, **edited.model_dump())
